globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"british-bulldog","year":2025,"grade":"2","contest":"British Bulldog","letters":"ABCD","count":30,"language":"en","points":3,"tasksFile":"2/tasks.pdf","answersFile":"reviewed-2.pdf","listeningFile":"2/listening.mp3","titleLanguage":"en","sections":[{"start":1,"title":"Listening"},{"start":6,"title":"Verb forms"},{"start":11,"title":"Word groups"},{"start":16,"title":"Jobs"},{"start":21,"title":"Family picture"},{"start":26,"title":"Things in a room"}],"reviewedKey":true}, [{"title":"The Letter Writer","question":"Who is writing the letter?","choices":["Sue","Ann","Emma","Helen"],"answer":0,"steps":["Послушай начало и конец письма. Dear Jane — это обращение к тому, кому пишут.","В конце девочка говорит «Love, Sue». Значит, письмо подписано именем Sue."],"audio":true,"context":"Listen to the girl’s letter and answer the questions."},{"title":"The Girl’s Occupation","question":"Who is she? She is a ... .","choices":["student","doctor","manager","teacher"],"answer":0,"steps":["Вопрос Who is she? здесь о том, чем занимается автор письма. Вслушайся в предложение сразу после приветствия.","Девочка говорит «I’m a student». Здесь student — ученица, потому что дальше она рассказывает о школе."],"audio":true,"context":"Listen to the girl’s letter and answer the questions."},{"title":"Where She Lives","question":"Where does she live? She lives ... .","choices":["in London","in a small village","in a little town","in a big town"],"answer":2,"steps":["Следи за двумя разными глаголами. Go to school сообщает, где она учится, а live — где живёт.","Она учится в Лондоне, а живёт «in a little town near London». Little town означает «маленький город»."],"audio":true,"context":"Listen to the girl’s letter and answer the questions."},{"title":"Her Pet","question":"What pet does she have?","choices":["A dog","A cat","A horse","A rabbit"],"answer":1,"steps":["Pet означает «домашнее животное». Ищи фразу, которая начинается словами «I also have …».","Девочка говорит «I also have a cat». Значит, её питомец — кошка."],"audio":true,"context":"Listen to the girl’s letter and answer the questions."},{"title":"The Pet’s Name","question":"What is its name?","choices":["Jane","Baby","Cori","Penny"],"answer":3,"steps":["Its относится к питомцу. Ищи его имя сразу после того, как девочка упоминает кошку.","Она говорит «Its name is Penny». Так зовут кошку. Jane — та, кому адресовано письмо."],"audio":true,"context":"Listen to the girl’s letter and answer the questions."},{"title":"His Name","question":"What ... his name?","choices":["am","is","are","have"],"answer":1,"steps":["His name означает «его имя». Здесь речь об одном имени.","С названием одного предмета употребляем is. Получается вопрос «What is his name?»."],"context":"Choose the correct word to complete the sentence."},{"title":"Talking About Age","question":"I ... eight years old.","choices":["am","is","are","has"],"answer":0,"steps":["Перед пропуском стоит I — «я». После него нужна форма глагола be.","С I употребляем am. «I am eight years old» означает «Мне восемь лет»."],"context":"Choose the correct word to complete the sentence."},{"title":"Having Breakfast","question":"I ... cheese for breakfast.","choices":["is","be","are","have"],"answer":3,"steps":["For breakfast означает «на завтрак». Нужно сказать, что человек ест сыр.","В таком предложении have означает «есть». С I подходит форма have."],"context":"Choose the correct word to complete the sentence."},{"title":"Nick’s Parrot","question":"Nick ... a parrot.","choices":["am","has","have","are"],"answer":1,"steps":["Ник — один человек, имя Nick можно заменить местоимением he. Нужно выразить, что у него есть попугай.","С he используем has. «Nick has a parrot» означает «У Ника есть попугай»."],"context":"Choose the correct word to complete the sentence."},{"title":"A Question of Origin","question":"They ... from the UK.","choices":["is","are","am","be"],"answer":1,"steps":["They означает «они». From the UK сообщает, откуда приехали или родом эти люди.","С they используем are. «They are from the UK» означает «Они из Великобритании»."],"context":"Choose the correct word to complete the sentence."},{"title":"Water and Tea","question":"Water, milk, tea, coffee, juice","choices":["Drinks","Colours","Plants","Pets"],"answer":0,"steps":["Переведи слова. Water — вода, tea — чай, juice — сок.","Воду, молоко, чай, кофе и сок можно пить. Все пять слов относятся к группе drinks."],"context":"Read the words and choose the group they belong to."},{"title":"Frog and Horse","question":"Frog, cow, horse, pig, cat","choices":["Animals","Birds","Plants","Family"],"answer":0,"steps":["Frog — лягушка, cow — корова, horse — лошадь. Найди общее название и для них, и для свиньи с кошкой.","Все они животные, animals. Вариант birds означает только птиц, а их в списке нет."],"context":"Read the words and choose the group they belong to."},{"title":"Sister and Uncle","question":"Sister, brother, mother, grandfather, uncle","choices":["Colours","Family","Food","Plants"],"answer":1,"steps":["Sister — сестра, brother — брат, uncle — дядя. Как связаны эти люди?","Все слова называют родственников. В английском их объединяет слово family — «семья»."],"context":"Read the words and choose the group they belong to."},{"title":"Coat and T-shirt","question":"Coat, T-shirt, dress, skirt, blouse","choices":["Animals","Birds","Colours","Clothes"],"answer":3,"steps":["Coat — пальто, T-shirt — футболка, dress — платье. Вспомни, что делают со всеми этими вещами.","Пальто, футболку, платье, юбку и блузку носят. Это clothes — «одежда»."],"context":"Read the words and choose the group they belong to."},{"title":"Bread and Apples","question":"Cheese, milk, apples, bread, sweets","choices":["Colours","Birds","Plants","Food"],"answer":3,"steps":["Bread — хлеб, apples — яблоки, sweets — сладости. Ищи категорию, куда входят также сыр и молоко.","Все эти продукты — food. Plants слишком узкое слово для этого списка, потому что сыр и молоко не растения."],"context":"Read the words and choose the group they belong to."},{"title":"Work in a Hospital","question":"He works in a hospital and treats patients.","choices":["A doctor","A painter","A photographer","A swimmer"],"answer":0,"steps":["Hospital означает «больница», а treats patients — «лечит пациентов». Посмотри, кто на рисунке под номером 16.","Лечит людей врач. На картинке у него медицинский халат и стетоскоп, а по-английски он a doctor."],"context":"Look at the picture and choose the job that matches the description.","figure":{"src":"assets/british-bulldog/2025/2/jobs.webp","alt":"Five numbered characters. The first wears a white coat and has a stethoscope. The second has a camera. The third holds a microphone. The fourth is in the water. The fifth has a brush and palette.","width":695,"height":462}},{"title":"Taking Pictures","question":"He takes pictures with a camera.","choices":["A photographer","A singer","A painter","A swimmer"],"answer":0,"steps":["Takes pictures with a camera означает «снимает фото камерой». На рисунке под номером 17 можно увидеть этот предмет.","Камерой пользуется фотограф, a photographer. Художника, который рисует картины, называют a painter."],"context":"Look at the picture and choose the job that matches the description.","figure":{"src":"assets/british-bulldog/2025/2/jobs.webp","alt":"Five numbered characters. The first wears a white coat and has a stethoscope. The second has a camera. The third holds a microphone. The fourth is in the water. The fifth has a brush and palette.","width":695,"height":462}},{"title":"Songs on Stage","question":"He sings songs.","choices":["A doctor","A photographer","A singer","A swimmer"],"answer":2,"steps":["Sings songs означает «поёт песни». Человек под номером 18 держит микрофон.","Человека, который поёт, называют a singer. Слова sing и singer связаны: «петь» и «певец»."],"context":"Look at the picture and choose the job that matches the description.","figure":{"src":"assets/british-bulldog/2025/2/jobs.webp","alt":"Five numbered characters. The first wears a white coat and has a stethoscope. The second has a camera. The third holds a microphone. The fourth is in the water. The fifth has a brush and palette.","width":695,"height":462}},{"title":"Moving Through Water","question":"He moves through water by moving his body.","choices":["A doctor","A swimmer","A singer","A painter"],"answer":1,"steps":["Moves through water означает «движется в воде». Под номером 19 видно, как человек гребёт руками.","Это пловец, a swimmer. Слово swimmer образовано от swim — «плавать»."],"context":"Look at the picture and choose the job that matches the description.","figure":{"src":"assets/british-bulldog/2025/2/jobs.webp","alt":"Five numbered characters. The first wears a white coat and has a stethoscope. The second has a camera. The third holds a microphone. The fourth is in the water. The fifth has a brush and palette.","width":695,"height":462}},{"title":"Making Pictures","question":"He paints pictures.","choices":["A doctor","A painter","A swimmer","A photographer"],"answer":1,"steps":["He paints pictures означает «Он пишет картины красками». Найди кисть и палитру на рисунке под номером 20.","Картины пишет a painter — художник. Фотограф, a photographer, делает снимки камерой."],"context":"Look at the picture and choose the job that matches the description.","figure":{"src":"assets/british-bulldog/2025/2/jobs.webp","alt":"Five numbered characters. The first wears a white coat and has a stethoscope. The second has a camera. The third holds a microphone. The fourth is in the water. The fifth has a brush and palette.","width":695,"height":462}},{"title":"Counting People","question":"How many people can you see?","choices":["2","3","4","5"],"answer":3,"steps":["People означает «люди». Сосчитай детей на коврике, человека на скамейке и людей у окна.","На коврике двое, на скамейке один, у окна двое. Всего 2 + 1 + 2 = 5 человек."],"context":"Look at the picture and answer the questions.","figure":{"src":"assets/british-bulldog/2025/2/family.webp","alt":"Two children are seated on a mat. The boy wears a blue top with short sleeves. A man looks at an open newspaper on a bench. A woman and a baby are behind an open window.","width":537,"height":554}},{"title":"The Girl on the Mat","question":"What is the girl doing? She is ... .","choices":["running","sitting","jumping","swimming"],"answer":1,"steps":["Вопрос What is the girl doing? означает «Что делает девочка?» Посмотри на её позу на коврике.","Она сидит, сложив ноги. «She is sitting» означает «Она сидит»."],"context":"Look at the picture and answer the questions.","figure":{"src":"assets/british-bulldog/2025/2/family.webp","alt":"Two children are seated on a mat. The boy wears a blue top with short sleeves. A man looks at an open newspaper on a bench. A woman and a baby are behind an open window.","width":537,"height":554}},{"title":"The Father on the Bench","question":"What is the father doing? He is ... .","choices":["reading","jumping","eating","sleeping"],"answer":0,"steps":["Найди отца на скамейке и посмотри, что у него в руках.","Он держит раскрытую газету и смотрит на неё. «He is reading» означает «Он читает»."],"context":"Look at the picture and answer the questions.","figure":{"src":"assets/british-bulldog/2025/2/family.webp","alt":"Two children are seated on a mat. The boy wears a blue top with short sleeves. A man looks at an open newspaper on a bench. A woman and a baby are behind an open window.","width":537,"height":554}},{"title":"The Boy’s Clothes","question":"What is the boy wearing?","choices":["A T-shirt","A dress","A coat","A sweater"],"answer":0,"steps":["What is the boy wearing? означает «Во что одет мальчик?» Найди мальчика на коврике и посмотри на рукава.","На нём голубая футболка с короткими рукавами. Футболка — a T-shirt."],"context":"Look at the picture and answer the questions.","figure":{"src":"assets/british-bulldog/2025/2/family.webp","alt":"Two children are seated on a mat. The boy wears a blue top with short sleeves. A man looks at an open newspaper on a bench. A woman and a baby are behind an open window.","width":537,"height":554}},{"title":"Mother and Baby","question":"Where are the mother and the baby? They are in the ... .","choices":["shop","park","garden","house"],"answer":3,"steps":["Найди маму с малышом и обрати внимание, с какой стороны окна они находятся.","Мама и малыш видны в окне изнутри дома. House означает «дом»."],"context":"Look at the picture and answer the questions.","figure":{"src":"assets/british-bulldog/2025/2/family.webp","alt":"Two children are seated on a mat. The boy wears a blue top with short sleeves. A man looks at an open newspaper on a bench. A woman and a baby are behind an open window.","width":537,"height":554}},{"title":"On the Wall","question":"There is a ... on the wall.","choices":["clock","chair","table","teddy bear"],"answer":0,"steps":["On the wall означает «на стене». Посмотри, какой из названных предметов прикреплён к стене.","На стене круглый предмет со стрелками — часы, a clock. Стол и стул стоят на полу."],"context":"Look at the picture and complete the sentence.","figure":{"src":"assets/british-bulldog/2025/2/room.webp","alt":"A blue seat with cushions is below a shelf and a round dial with hands. A green reading light rests on the desk, with a red wheeled seat in front and a glazed opening above.","width":649,"height":496}},{"title":"On the Table","question":"There is a ... on the table.","choices":["lamp","ball","car","book"],"answer":0,"steps":["On the table означает «на столе». Найди стол справа и проверь, что стоит на столешнице.","На краю стола стоит зелёная настольная лампа. Lamp означает «лампа»."],"context":"Look at the picture and complete the sentence.","figure":{"src":"assets/british-bulldog/2025/2/room.webp","alt":"A blue seat with cushions is below a shelf and a round dial with hands. A green reading light rests on the desk, with a red wheeled seat in front and a glazed opening above.","width":649,"height":496}},{"title":"Under the Shelf","question":"There is a ... under the shelf and the clock.","choices":["sofa","plant","globe","ball"],"answer":0,"steps":["Under означает «под». Найди полку и часы на стене, а затем посмотри чуть ниже.","Под ними стоит диван с подушками. Диван — a sofa."],"context":"Look at the picture and complete the sentence.","figure":{"src":"assets/british-bulldog/2025/2/room.webp","alt":"A blue seat with cushions is below a shelf and a round dial with hands. A green reading light rests on the desk, with a red wheeled seat in front and a glazed opening above.","width":649,"height":496}},{"title":"Above the Table","question":"There is a ... above the table.","choices":["carpet","chair","sofa","window"],"answer":3,"steps":["Above означает «выше, над». Найди стол в правой части картинки и подними взгляд.","Над столом видно окно со шторой. Окно — a window."],"context":"Look at the picture and complete the sentence.","figure":{"src":"assets/british-bulldog/2025/2/room.webp","alt":"A blue seat with cushions is below a shelf and a round dial with hands. A green reading light rests on the desk, with a red wheeled seat in front and a glazed opening above.","width":649,"height":496}},{"title":"In Front of the Table","question":"There is a ... in front of the table.","choices":["chair","clock","plant","book"],"answer":0,"steps":["In front of the table означает «перед столом». Посмотри, какой предмет мебели расположен прямо перед ним.","Перед столом стоит красный стул на колёсиках. Chair означает «стул»."],"context":"Look at the picture and complete the sentence.","figure":{"src":"assets/british-bulldog/2025/2/room.webp","alt":"A blue seat with cushions is below a shelf and a round dial with hands. A green reading light rests on the desk, with a red wheeled seat in front and a glazed opening above.","width":649,"height":496}}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
